import{_ as t,o as i,c as s,a2 as a}from"./chunks/framework.DPo9QYCX.js";const u=JSON.parse('{"title":"Installation Info","description":"","frontmatter":{},"headers":[],"relativePath":"install_tips.md","filePath":"install_tips.md","lastUpdated":null}'),n={name:"install_tips.md"};function l(o,e,r,d,c,h){return i(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="Installation-Info" tabindex="-1">Installation Info <a class="header-anchor" href="#Installation-Info" aria-label="Permalink to &quot;Installation Info {#Installation-Info}&quot;">​</a></h1><h2 id="ROCm-libraries" tabindex="-1">ROCm libraries <a class="header-anchor" href="#ROCm-libraries" aria-label="Permalink to &quot;ROCm libraries {#ROCm-libraries}&quot;">​</a></h2><p>By default, AMDGPU.jl downloads the ROCm runtime (HIP and HSA) and libraries (rocBLAS, rocSOLVER, rocSPARSE, rocFFT, rocRAND, MIOpen and hipTensor) as artifacts, taken from AMD&#39;s <a href="https://github.com/ROCm/TheRock" target="_blank" rel="noreferrer">TheRock</a> distribution for the GPUs detected on the host. No ROCm installation is needed, only the GPU driver. The kernel linker and the device libraries always come from <code>AMDGPU_LLVM_Backend_jll</code>; the device libraries are converted to the LLVM version of the running Julia on first use and cached in the depot.</p><p>To use a local ROCm installation instead, set the <code>local</code> preference and restart Julia:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">AMDGPU</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">set_rocm_version!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(local_rocm</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>Its libraries are then found as described in <a href="/previews/PR1221/install_tips#Local-ROCm-discovery">Local ROCm discovery</a>. <code>AMDGPU.reset_rocm_version!()</code> goes back to the artifacts.</p><h3 id="Selecting-the-provider-before-installing" tabindex="-1">Selecting the provider before installing <a class="header-anchor" href="#Selecting-the-provider-before-installing" aria-label="Permalink to &quot;Selecting the provider before installing {#Selecting-the-provider-before-installing}&quot;">​</a></h3><p>Pkg reads the <code>local</code> preference when it installs the artifacts, so in CI or a fresh depot set it before <code>Pkg.instantiate()</code> to avoid downloading a bundle that will not be used. <code>AMDGPU.set_rocm_version!</code> needs AMDGPU.jl to be installed, so write the preference by hand instead, under <code>[ROCm_Runtime]</code> in the project&#39;s <code>LocalPreferences.toml</code> (see <a href="/previews/PR1221/install_tips#Preferences">Preferences</a>):</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ROCm_Runtime</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">local = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><p>Unless <code>ROCm_Runtime</code> is a direct dependency, Julia only reads this section when the project&#39;s <code>Project.toml</code> lists the package (<code>AMDGPU.set_rocm_version!</code> adds this entry itself):</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">extras</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ROCm_Runtime = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;3129f4d2-de71-4ff3-9833-76037e3ea355&quot;</span></span></code></pre></div><p><code>AMDGPU.local_rocm</code> tells which provider was selected. Asserting on it in CI keeps a change of default from silently switching the ROCm a job tests.</p><h3 id="When-no-artifact-matches" tabindex="-1">When no artifact matches <a class="header-anchor" href="#When-no-artifact-matches" aria-label="Permalink to &quot;When no artifact matches {#When-no-artifact-matches}&quot;">​</a></h3><p>The bundle is chosen from the GPU architectures detected on the host, which on Linux are read from <code>/sys/class/kfd/kfd/topology</code>. If none is detected (in a container without <code>/dev/kfd</code>, on a login node, or when the <code>amdgpu</code> driver is not loaded), or no bundle supports it, nothing is downloaded, and AMDGPU.jl warns and reports its ROCm components as unavailable. It does not fall back to a ROCm installed on the system; that one is only used with the <code>local</code> preference.</p><p>The bundles currently shipped are:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Bundle</th><th style="text-align:left;">Platforms</th><th style="text-align:left;">ROCm</th></tr></thead><tbody><tr><td style="text-align:left;"><code>gfx101x_dgpu</code></td><td style="text-align:left;">linux, windows</td><td style="text-align:left;">10.1</td></tr><tr><td style="text-align:left;"><code>gfx103x_all</code></td><td style="text-align:left;">linux, windows</td><td style="text-align:left;">10.1</td></tr><tr><td style="text-align:left;"><code>gfx110x_all</code></td><td style="text-align:left;">linux, windows</td><td style="text-align:left;">10.1</td></tr><tr><td style="text-align:left;"><code>gfx1150</code></td><td style="text-align:left;">linux, windows</td><td style="text-align:left;">10.1</td></tr><tr><td style="text-align:left;"><code>gfx1151</code></td><td style="text-align:left;">linux, windows</td><td style="text-align:left;">10.1</td></tr><tr><td style="text-align:left;"><code>gfx1152</code></td><td style="text-align:left;">linux, windows</td><td style="text-align:left;">10.1</td></tr><tr><td style="text-align:left;"><code>gfx1153</code></td><td style="text-align:left;">linux, windows</td><td style="text-align:left;">10.1</td></tr><tr><td style="text-align:left;"><code>gfx120x_all</code></td><td style="text-align:left;">linux, windows</td><td style="text-align:left;">10.1</td></tr><tr><td style="text-align:left;"><code>gfx125x_dcgpu</code></td><td style="text-align:left;">linux</td><td style="text-align:left;">10.1</td></tr><tr><td style="text-align:left;"><code>gfx908</code></td><td style="text-align:left;">linux, windows</td><td style="text-align:left;">10.1</td></tr><tr><td style="text-align:left;"><code>gfx90a</code></td><td style="text-align:left;">linux, windows</td><td style="text-align:left;">10.1</td></tr><tr><td style="text-align:left;"><code>gfx94x_dcgpu</code></td><td style="text-align:left;">linux</td><td style="text-align:left;">10.1</td></tr><tr><td style="text-align:left;"><code>gfx950_dcgpu</code></td><td style="text-align:left;">linux</td><td style="text-align:left;">10.1</td></tr></tbody></table><p>When the architecture cannot be detected, for example when preparing a depot on a machine without a GPU, select the bundle with the <code>arch</code> preference, a <code>gfx</code> target or a collection of them:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">AMDGPU</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">set_rocm_version!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(arch</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;gfx942&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>Like <code>local</code>, it can also be written to <code>LocalPreferences.toml</code> before AMDGPU.jl is installed.</p><p>The <code>version</code> preference selects the ROCm release the bundle is taken from, by default the newest one listed above.</p><h2 id="Local-ROCm-discovery" tabindex="-1">Local ROCm discovery <a class="header-anchor" href="#Local-ROCm-discovery" aria-label="Permalink to &quot;Local ROCm discovery {#Local-ROCm-discovery}&quot;">​</a></h2><p>Everything in this section applies only when the <code>local</code> preference is set, which needs ROCm 6.0 or newer installed on the system. In the default artifact mode the library paths come from the downloaded bundle and <code>ROCM_PATH</code> is not consulted; a ROCm reachable through <code>LD_LIBRARY_PATH</code> or the device-library variables is still picked up by the runtime and mixed into the process, see the <a href="/previews/PR1221/faq#FAQ">FAQ</a>.</p><p>The ROCm root is taken from <code>ROCM_PATH</code> if set, on Linux otherwise from <code>hipconfig --rocmpath</code>, and failing that from the standard paths:</p><ul><li><p>Linux: <code>/opt/rocm</code>, <code>/usr</code></p></li><li><p>Windows: <code>C:/Program Files/AMD/ROCm/&lt;rocm-version&gt;</code></p></li></ul><p>If you have non-standard path for ROCm, set <code>ROCM_PATH=&lt;path&gt;</code> environment variable before launching Julia. The <code>AMDGPU.versioninfo()</code> function prints the paths of any libraries found.</p><div class="tip custom-block"><p class="custom-block-title">On Fedora ROCm packages</p><p>Although not included in the AMD&#39;s list of supported Linux distributions, Fedora provides its own ROCM packages.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo dnf install rocminfo rocblas rocfft rocsparse rocsolver rocrand roctracer miopen rocm-hip-devel</span></span></code></pre></div></div><p>Starting with ROCm 7.14, libraries are installed under a versioned <code>core-&lt;version&gt;</code> subdirectory (for example <code>/opt/rocm/core-7.14/lib</code>) instead of directly in <code>/opt/rocm/lib</code>. AMDGPU.jl handles this automatically by selecting the newest <code>core-*</code> directory found under the ROCm root, so keep <code>ROCM_PATH</code> pointed at the install root (e.g. <code>/opt/rocm</code>) rather than at the versioned subdirectory. A full (&quot;metapackage&quot;) install additionally provides a <code>/opt/rocm/lib</code> compatibility symlink and needs no special handling; the versioned lookup mainly benefits minimal, GPU-architecture-specific installs that omit that symlink.</p><h2 id="GPU-selection-and-architecture-overrides" tabindex="-1">GPU selection and architecture overrides <a class="header-anchor" href="#GPU-selection-and-architecture-overrides" aria-label="Permalink to &quot;GPU selection and architecture overrides {#GPU-selection-and-architecture-overrides}&quot;">​</a></h2><p>These also apply with the artifacts, as they are read by the ROCm runtime itself.</p><p>Depending on your GPU model and the functionality you want to use, you may have to force the GPU architecture by setting the <code>HSA_OVERRIDE_GFX_VERSION</code> variable to a compatible version.</p><p>You may also have more than one type of GPU, for example a dedicated AMD GPU and an integrated one. In that case use <code>AMDGPU.devices()</code> to find which device they are and set <code>HIP_VISIBLE_DEVICES</code> to the specific device you want to use. Otherwise the runtime may crash if it sees two different architectures.</p><h2 id="Extra-Setup-Details" tabindex="-1">Extra Setup Details <a class="header-anchor" href="#Extra-Setup-Details" aria-label="Permalink to &quot;Extra Setup Details {#Extra-Setup-Details}&quot;">​</a></h2><p>List of additional steps that may be needed to take to ensure everything is working:</p><ul><li><p>Make sure your user is in the same group as <code>/dev/kfd</code>, other than <code>root</code>. For example, it might be the <code>render</code> group: <code>crw-rw---- 1 root render 234, 0 Aug 5 11:43 kfd</code> In this case, you can add yourself to it: <code>sudo usermod -aG render username</code></p></li><li><p>With a local ROCm, if you get an error message along the lines of <code>GLIB_CXX_... not found</code>, it&#39;s possible that the C++ runtime used to build the ROCm stack and the one used by Julia are different. If you built the ROCm stack yourself this is very likely the case since Julia normally ships with its own C++ runtime. For more information, check out this <a href="https://github.com/JuliaLang/julia/issues/34276" target="_blank" rel="noreferrer">GitHub issue</a>. A quick fix is to use the <code>LD_PRELOAD</code> environment variable to make Julia use the system C++ runtime library, for example: <code>LD_PRELOAD=/usr/lib/libstdc++.so julia</code> Alternatively, you can build Julia from source as described <a href="https://github.com/JuliaLang/julia/blob/master/doc/build/build.md" target="_blank" rel="noreferrer">here</a>. To quickly debug this issue start Julia and try to load a ROCm library: <code>using Libdl Libdl.dlopen(&quot;/opt/rocm/lib/libhsa-runtime64.so.1&quot;)</code></p></li></ul><p>Once all of this is setup properly, you should be able to do <code>using AMDGPU</code> successfully.</p><p>See the <a href="/previews/PR1221/tutorials/quickstart#Quick-Start">Quick Start</a> documentation for an introduction to using AMDGPU.jl.</p><h2 id="Preferences" tabindex="-1">Preferences <a class="header-anchor" href="#Preferences" aria-label="Permalink to &quot;Preferences {#Preferences}&quot;">​</a></h2><p>AMDGPU.jl supports setting <a href="https://github.com/JuliaPackaging/Preferences.jl" target="_blank" rel="noreferrer">preferences</a>; see <a href="/previews/PR1221/api/system#Configuration-preferences">Configuration preferences</a> for the full list. Template of <code>LocalPreferences.toml</code>:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ROCm_Runtime</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Only read when \`ROCm_Runtime\` is in the \`[extras]\` of Project.toml (see above).</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Use a local ROCm installation instead of the downloaded artifacts (default is &quot;false&quot;).</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">local = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;false&quot;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ROCm distribution to download (default is the newest one shipped), and the GPU</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># architectures to select it for when none can be detected (see above).</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># version = &quot;10.1&quot;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># arch = &quot;gfx942&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">AMDGPU</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># If \`true\` (default is \`false\`), eagerly run GC to keep the pool from growing too big.</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># GC is triggered during new allocatoins or synchronization points.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">eager_gc = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Use non-blocking synchronization for all \`AMDGPU.synchronize()\` calls (default is \`true\`).</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">nonblocking_synchronization = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Memory limit specifies maximum amount of memory in percentages</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># a current Julia process can use.</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Default is &quot;none&quot;, which does not apply any limitation.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">hard_memory_limit = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;none&quot;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Notice a space between the value and percentage sign.</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># hard_memory_limit = &quot;80 %&quot;</span></span></code></pre></div>`,39)])])}const g=t(n,[["render",l]]);export{u as __pageData,g as default};
